1	//! Tensor-parallel assignment and validated local geometry for Qwen3.5.
2	//!
3	//! Directional boundary: this module depends on [`super::model`] (it reads a
4	//! validated [`Config35`] to derive shard dimensions), but [`super::model`] is
5	//! TP-agnostic and never depends on it. Downstream code accepts the validated
6	//! [`LocalGeometry`] type produced here instead of re-deriving shards from a
7	//! raw `(rank, world_size)` pair.
8	//!
9	//! Both [`TensorParallelConfig`] and [`LocalGeometry`] validate at construction:
10	//! an invalid assignment is unrepresentable, and a model that disagrees with the
11	//! TP world is rejected before any weights are mapped.
12	
13	use super::error::ConfigError;
14	use super::model::Config35;
15	
16	/// A validated tensor-parallel assignment.
17	///
18	/// Fields are private so an invalid state (`world_size == 0`, `rank >=
19	/// world_size`) cannot be constructed. The only way to obtain one is
20	/// [`Self::try_from`] or [`Default`] (single-rank).
21	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
22	pub(crate) struct TensorParallelConfig {
23	    rank: usize,
24	    world_size: usize,
25	}
26	
27	impl Default for TensorParallelConfig {
28	    fn default() -> Self {
29	        Self {
30	            rank: 0,
31	            world_size: 1,
32	        }
33	    }
34	}
35	
36	impl TensorParallelConfig {
37	    pub(crate) fn rank(self) -> usize {
38	        self.rank
39	    }
40	
41	    pub(crate) fn world_size(self) -> usize {
42	        self.world_size
43	    }
44	
45	    pub(crate) fn is_sharded(self) -> bool {
46	        self.world_size > 1
47	    }
48	
49	    /// Split a global row count into this rank's `(offset, len)`.
50	    pub(crate) fn shard_range(self, total: usize) -> (usize, usize) {
51	        let shard_len = total / self.world_size;
52	        (self.rank * shard_len, shard_len)
53	    }
54	}
55	
56	/// Validate an assignment independently of any model geometry.
57	impl TryFrom<(usize, usize)> for TensorParallelConfig {
58	    type Error = ConfigError;
59	
60	    fn try_from((rank, world_size): (usize, usize)) -> Result<Self, Self::Error> {
61	        if world_size == 0 {
62	            return Err(ConfigError::TpZeroWorldSize);
63	        }
64	        if rank >= world_size {
65	            return Err(ConfigError::TpRankOutOfRange { rank, world_size });
66	        }
67	        Ok(Self { rank, world_size })
68	    }
69	}
70	
71	/// Validated per-rank shard geometry for a Qwen3.5 model under a TP assignment.
72	///
73	/// Built once from a validated model config + TP assignment + cuda-graph mode;
74	/// every model cross-field and TP/kernel compatibility rule is enforced here.
75	/// Downstream code sizes buffers and computes shards from this type, never from
76	/// a raw rank/world-size pair.
77	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
78	pub(crate) struct LocalGeometry {
79	    tp: TensorParallelConfig,
80	    local_num_attention_heads: usize,
81	    local_num_key_value_heads: usize,
82	    local_intermediate_size: usize,
83	    local_full_attn_q_dim: usize,
84	    local_full_attn_kv_dim: usize,
85	    local_full_attn_gated_q_dim: usize,
86	    local_linear_num_key_heads: usize,
87	    local_linear_num_value_heads: usize,
88	    local_linear_v_dim: usize,
89	    local_linear_qkv_dim: usize,
90	}
91	
92	impl LocalGeometry {
93	    /// Validate `config` against `tp`, then derive this rank's local dimensions.
94	    ///
95	    /// Fails on unsupported combinations before expensive loading:
96	    /// - every sharded model dimension must divide evenly by `world_size`
97	    ///   (linear-attention key heads included; the value-head count follows
98	    ///   from the `Config35` key/value-head invariant);
99	    /// - `rank < world_size` and `world_size >= 1` are guaranteed by
100	    ///   `TensorParallelConfig::try_from`.
101	    ///
102	    /// CUDA Graph under TP is gated at executor startup on
103	    /// [`Config35::decode_group_is_compiled`] (P2c): uncompiled GQA
104	    /// groups keep the batched eager path instead of failing validation here.
105	    pub(crate) fn try_new(
106	        config: &Config35,
107	        tp: TensorParallelConfig,
108	    ) -> Result<Self, ConfigError> {
109	        if !config.num_attention_heads.is_multiple_of(tp.world_size()) {
110	            return Err(ConfigError::TpIndivisible {
111	                field: "num_attention_heads",
112	                value: config.num_attention_heads,
113	                world_size: tp.world_size(),
114	            });
115	        }
116	        if !config.num_key_value_heads.is_multiple_of(tp.world_size()) {
117	            return Err(ConfigError::TpIndivisible {
118	                field: "num_key_value_heads",
119	                value: config.num_key_value_heads,
120	                world_size: tp.world_size(),
121	            });
122	        }
123	        if !config.intermediate_size.is_multiple_of(tp.world_size()) {
124	            return Err(ConfigError::TpIndivisible {
125	                field: "intermediate_size",
126	                value: config.intermediate_size,
127	                world_size: tp.world_size(),
128	            });
129	        }
130	        // Fail closed on an indivisible key-head count rather than falling
131	        // back to replication.
132	        if !config.linear_num_key_heads.is_multiple_of(tp.world_size()) {
133	            return Err(ConfigError::TpIndivisible {
134	                field: "linear_num_key_heads",
135	                value: config.linear_num_key_heads,
136	                world_size: tp.world_size(),
137	            });
138	        }
139	
140	        let local_num_attention_heads = config.num_attention_heads / tp.world_size();
141	        let local_num_key_value_heads = config.num_key_value_heads / tp.world_size();
142	        let local_intermediate_size = config.intermediate_size / tp.world_size();
143	        let local_full_attn_q_dim = local_num_attention_heads * config.head_dim;
144	        let local_full_attn_kv_dim = local_num_key_value_heads * config.head_dim;
145	        let local_linear_num_key_heads = config.linear_num_key_heads / tp.world_size();
146	        let local_linear_num_value_heads = config.linear_num_value_heads / tp.world_size();
147	        // Local q/k segment rows of the fused linear-attention qkv projection;
148	        // q is keyed by key heads (one key head per value-head group).
149	        let local_linear_q_dim = local_linear_num_key_heads * config.linear_key_head_dim;
150	        let local_linear_v_dim = local_linear_num_value_heads * config.linear_value_head_dim;
151	
152	        Ok(Self {
153	            tp,
154	            local_num_attention_heads,
155	            local_num_key_value_heads,
156	            local_intermediate_size,
157	            local_full_attn_q_dim,
158	            local_full_attn_kv_dim,
159	            local_full_attn_gated_q_dim: local_full_attn_q_dim * 2,
160	            local_linear_num_key_heads,
161	            local_linear_num_value_heads,
162	            local_linear_v_dim,
163	            // k rows mirror q rows.
164	            local_linear_qkv_dim: local_linear_q_dim * 2 + local_linear_v_dim,
165	        })
166	    }
167	
