169	        self.tp.rank()
170	    }
171	
172	    pub(crate) fn world_size(&self) -> usize {
173	        self.tp.world_size()
174	    }
175	
176	    pub(crate) fn is_sharded(&self) -> bool {
177	        self.tp.is_sharded()
178	    }
179	
180	    pub(crate) fn shard_range(&self, total: usize) -> (usize, usize) {
181	        self.tp.shard_range(total)
182	    }
183	
184	    pub(crate) fn local_num_attention_heads(&self) -> usize {
185	        self.local_num_attention_heads
186	    }
187	
188	    pub(crate) fn local_num_key_value_heads(&self) -> usize {
189	        self.local_num_key_value_heads
190	    }
191	
192	    pub(crate) fn local_intermediate_size(&self) -> usize {
193	        self.local_intermediate_size
194	    }
195	
196	    pub(crate) fn local_full_attn_q_dim(&self) -> usize {
197	        self.local_full_attn_q_dim
198	    }
199	
200	    pub(crate) fn local_full_attn_kv_dim(&self) -> usize {
201	        self.local_full_attn_kv_dim
202	    }
203	
204	    /// Local gated full-attention q projection output dimension.
205	    pub(crate) fn local_full_attn_gated_q_dim(&self) -> usize {
206	        self.local_full_attn_gated_q_dim
207	    }
208	
209	    // TP1 contract: at world_size 1 every local dim equals the global dim, so
210	    // all linear-attention kernels/buffers/state keep their pre-TP shapes.
211	
212	    pub(crate) fn local_linear_num_key_heads(&self) -> usize {
213	        self.local_linear_num_key_heads
214	    }
215	
216	    pub(crate) fn local_linear_num_value_heads(&self) -> usize {
217	        self.local_linear_num_value_heads
218	    }
219	
220	    /// Local fused qkv projection rows (q, k and v segments, each head-local).
221	    pub(crate) fn local_linear_qkv_dim(&self) -> usize {
222	        self.local_linear_qkv_dim
223	    }
224	
225	    /// Local z projection output dimension (equals local v dim).
226	    pub(crate) fn local_linear_z_dim(&self) -> usize {
227	        self.local_linear_v_dim
228	    }
229	}
