379	    #[test]
380	    fn unknown_layer_type_is_typed() {
381	        let json = VALID_RAW.replace("linear_attention", "window_attention");
382	        let err = Config35::try_from(parse(&json)).unwrap_err();
383	        assert_eq!(
384	            err,
385	            ConfigError::UnknownLayerType("window_attention".to_string())
386	        );
387	    }
388	
389	    #[test]
390	    fn layer_type_count_mismatch_is_typed() {
391	        let json = VALID_RAW.replace(
392	            "[\"linear_attention\", \"full_attention\"]",
393	            "[\"linear_attention\"]",
394	        );
395	        let err = Config35::try_from(parse(&json)).unwrap_err();
396	        assert_eq!(
397	            err,
398	            ConfigError::LayerTypeCountMismatch {
399	                actual: 1,
400	                expected: 2,
401	            }
402	        );
403	    }
404	
405	    #[test]
406	    fn missing_max_position_embeddings_is_typed() {
407	        let json = VALID_RAW.replace("\"max_position_embeddings\": 4096,", "");
408	        let err = Config35::try_from(parse(&json)).unwrap_err();
409	        assert_eq!(err, ConfigError::MissingMaxPositionEmbeddings);
410	    }
411	
412	    #[test]
413	    fn wide_linear_conv_kernel_is_typed() {
414	        let json = VALID_RAW.replace(
415	            "\"linear_conv_kernel_dim\": 4",
416	            "\"linear_conv_kernel_dim\": 5",
417	        );
418	        let err = Config35::try_from(parse(&json)).unwrap_err();
419	        assert_eq!(
420	            err,
421	            ConfigError::LinearConvKernelDim {
422	                max: LINEAR_CONV_MAX_KERNEL_DIM,
423	                actual: 5,
424	            }
425	        );
426	    }
